"""
Human-in-the-Loop Review Portal — FastAPI :7000
Web UI for humans to review, approve, reject agent actions.
"""
import asyncio
from fastapi           import FastAPI, Request, Form
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.middleware.cors import CORSMiddleware

from core.hitl.checkpoint import get_checkpoint_manager
from core.models          import HITLResponse, HITLDecision

app = FastAPI(title="HITL Review Portal")
app.add_middleware(CORSMiddleware, allow_origins=["*"],
                   allow_methods=["*"], allow_headers=["*"])

# ── HTML Portal ───────────────────────────────────
@app.get("/", response_class=HTMLResponse)
async def portal():
    return """
<!DOCTYPE html>
<html>
<head>
  <title>🤝 A2A + MCP + HITL Portal</title>
  <meta http-equiv="refresh" content="3">
  <style>
    body { font-family: monospace; background: #0d1117; color: #c9d1d9;
           max-width: 900px; margin: 0 auto; padding: 20px; }
    h1   { color: #58a6ff; }
    h2   { color: #f0883e; border-bottom: 1px solid #30363d; padding-bottom: 8px; }
    .card { background: #161b22; border: 1px solid #30363d;
            border-radius: 8px; padding: 16px; margin: 12px 0; }
    .badge { padding: 3px 10px; border-radius: 12px; font-size: 12px; font-weight: bold; }
    .pending  { background: #9e6a03; color: #fff; }
    .resolved { background: #1a7f37; color: #fff; }
    .content  { background: #0d1117; padding: 10px; border-radius: 4px;
                border-left: 3px solid #58a6ff; margin: 10px 0;
                white-space: pre-wrap; font-size: 13px; max-height: 200px;
                overflow-y: auto; }
    .btn { padding: 8px 20px; border: none; border-radius: 6px;
           cursor: pointer; font-size: 14px; font-weight: bold; margin: 4px; }
    .approve { background: #238636; color: white; }
    .reject  { background: #da3633; color: white; }
    .modify  { background: #9e6a03; color: white; }
    textarea { width: 100%; background: #0d1117; color: #c9d1d9;
               border: 1px solid #30363d; border-radius: 4px;
               padding: 8px; font-family: monospace; font-size: 13px; }
    .meta    { color: #8b949e; font-size: 12px; margin-bottom: 8px; }
    .empty   { color: #8b949e; text-align: center; padding: 40px; }
    .stats   { display: flex; gap: 20px; margin-bottom: 20px; }
    .stat    { background: #161b22; border: 1px solid #30363d;
               border-radius: 8px; padding: 12px 20px; text-align: center; }
    .stat-n  { font-size: 28px; font-weight: bold; color: #58a6ff; }
    .stat-l  { font-size: 12px; color: #8b949e; }
  </style>
</head>
<body>
  <h1>🤝 A2A + MCP + HITL Review Portal</h1>
  <p style="color:#8b949e">Auto-refreshes every 3 seconds</p>

  <div id="stats" class="stats"></div>

  <h2>⏳ Pending Approvals</h2>
  <div id="pending">Loading...</div>

  <h2>✅ Resolved Checkpoints</h2>
  <div id="resolved">Loading...</div>

  <script>
    async function load() {
      const r    = await fetch('/api/checkpoints');
      const data = await r.json();
      const all  = data.checkpoints;
      const pending  = all.filter(c => c.checkpoint.status === 'pending');
      const resolved = all.filter(c => c.checkpoint.status === 'resolved');

      // Stats
      document.getElementById('stats').innerHTML = `
        <div class="stat"><div class="stat-n">${all.length}</div><div class="stat-l">Total</div></div>
        <div class="stat"><div class="stat-n" style="color:#f0883e">${pending.length}</div><div class="stat-l">Pending</div></div>
        <div class="stat"><div class="stat-n" style="color:#3fb950">${resolved.length}</div><div class="stat-l">Resolved</div></div>
      `;

      // Pending
      if (pending.length === 0) {
        document.getElementById('pending').innerHTML = '<div class="empty">No pending approvals 🎉</div>';
      } else {
        document.getElementById('pending').innerHTML = pending.map(c => renderCard(c, true)).join('');
      }

      // Resolved
      if (resolved.length === 0) {
        document.getElementById('resolved').innerHTML = '<div class="empty">None yet</div>';
      } else {
        document.getElementById('resolved').innerHTML = resolved.slice(-5).reverse()
          .map(c => renderCard(c, false)).join('');
      }
    }

    function renderCard(item, showActions) {
      const cp   = item.checkpoint;
      const resp = item.response;
      const badge = cp.status === 'pending'
        ? '<span class="badge pending">PENDING</span>'
        : `<span class="badge resolved">${resp?.decision?.toUpperCase() || 'RESOLVED'}</span>`;

      const actions = showActions ? `
        <div style="margin-top:12px">
          <textarea id="mod_${cp.checkpoint_id}" rows="3"
            placeholder="Modified content (optional)...">${cp.content}</textarea>
          <div style="margin-top:8px">
            <button class="btn approve" onclick="decide('${cp.checkpoint_id}','approved')">✅ Approve</button>
            <button class="btn reject"  onclick="decide('${cp.checkpoint_id}','rejected')">❌ Reject</button>
            <button class="btn modify"  onclick="decide('${cp.checkpoint_id}','modified')">✏️ Approve Modified</button>
          </div>
          <input id="fb_${cp.checkpoint_id}" style="width:100%;margin-top:6px;
            background:#0d1117;color:#c9d1d9;border:1px solid #30363d;
            border-radius:4px;padding:6px;font-family:monospace"
            placeholder="Optional feedback...">
        </div>` : resp ? `
        <div style="margin-top:8px;color:#8b949e;font-size:12px">
          Decision: <b style="color:#3fb950">${resp.decision}</b> |
          By: ${resp.reviewer} | Feedback: ${resp.feedback || '—'}
        </div>` : '';

      return `
        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <b style="color:#58a6ff">${cp.title}</b>
            ${badge}
          </div>
          <div class="meta">
            Agent: ${cp.agent_name} | Type: ${cp.checkpoint_type} |
            Task: ${cp.task_id.substring(0,8)} | ${cp.created_at.substring(0,19)}
          </div>
          <div style="color:#8b949e;margin-bottom:8px">${cp.description}</div>
          <div class="content">${cp.content.substring(0,500)}${cp.content.length>500?'...':''}</div>
          ${actions}
        </div>`;
    }

    async function decide(id, decision) {
      const feedback = document.getElementById('fb_'+id)?.value || '';
      const modified = document.getElementById('mod_'+id)?.value || '';
      await fetch('/api/respond', {
        method: 'POST',
        headers: {'Content-Type':'application/json'},
        body: JSON.stringify({
          checkpoint_id:    id,
          decision:         decision,
          feedback:         feedback,
          modified_content: decision === 'modified' ? modified : null,
        }),
      });
      load();
    }

    load();
    setInterval(load, 3000);
  </script>
</body>
</html>
"""

@app.get("/api/checkpoints")
async def get_checkpoints():
    mgr = get_checkpoint_manager()
    return {"checkpoints": mgr.get_all()}

@app.post("/api/respond")
async def respond(request: Request):
    body     = await request.json()
    mgr      = get_checkpoint_manager()
    response = HITLResponse(
        checkpoint_id    = body["checkpoint_id"],
        decision         = HITLDecision(body["decision"]),
        feedback         = body.get("feedback", ""),
        modified_content = body.get("modified_content"),
        reviewer         = "human_via_portal",
    )
    success = await mgr.submit_response(response)
    return {"success": success}

@app.get("/api/stats")
async def stats():
    mgr  = get_checkpoint_manager()
    all_ = mgr.get_all()
    return {
        "total":    len(all_),
        "pending":  sum(1 for c in all_ if c["checkpoint"]["status"] == "pending"),
        "resolved": sum(1 for c in all_ if c["checkpoint"]["status"] == "resolved"),
    }

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=7000)
